import type { ViewConfig } from "@perspective-dev/client";

/**
 * Detail payload for the `perspective-click` CustomEvent dispatched on
 * the `<perspective-viewer>` host when the user clicks a chart glyph.
 * Shape matches the equivalent type in `@perspective-dev/viewer-datagrid`
 * so consumers can listen to either plugin uniformly.
 */
export interface PerspectiveClickDetail {
    /**
     * Source-view row data — keys are column names, values are scalar
     * cell values. Empty `{}` when the click hit a non-leaf aggregate
     * (e.g. a treemap branch).
     */
    row: Record<string, unknown>;

    /**
     * Aggregate column(s) the click targeted. Single-entry for series /
     * heatmap / tree charts; multi-entry would only appear for plugins
     * that surface multiple measures per glyph (none today).
     */
    column_names: string[];

    /**
     * Pre-built `viewer.restore({ filter })` patch — concatenates the
     * group_by and split_by pivot values at the click target as
     * `[<col>, "==", <value>]` clauses.
     */
    config: Partial<ViewConfig>;

    /**
     * The source panel's `slot` name in a multi-panel `<perspective-viewer>`,
     * so the host can attribute the click to the originating panel. `undefined`
     * for a lone, unslotted viewer. Mirrors `PerspectiveSelectDetail.panel` and
     * the datagrid `PerspectiveClickDetail`.
     */
    panel?: string;
}

/**
 * A chart mark resolved to its view row, measure column and pivot values.
 */
export interface ClickTarget {
    rowIdx: number | null;
    columnName: string;
    groupByValues: (string | number | null)[];
    splitByValues: (string | number | null)[];
}

/**
 * What a chart rendered at a point, as its plugin's `hit_test` reports it: a
 * one-row frame cut from the mark's `ClickTarget` and the location in it.
 */
export interface ChartHit {
    frame: PerspectiveViewFrame;
    ref: PerspectiveHitRef;
}

/**
 * The `{ frame, ref }` for a mark, built from its `ClickTarget` alone so no
 * row fetch runs; a mark without a view row yields a column-only location.
 */
export function chartHitFromTarget(target: ClickTarget): ChartHit {
    const key = [...target.splitByValues, target.columnName]
        .map((v) => (v == null ? "" : String(v)))
        .join("|");

    const y =
        target.rowIdx != null && target.rowIdx >= 0 ? target.rowIdx : undefined;
    const data: Record<string, unknown[]> = {};
    if (y !== undefined) {
        data["__ROW_PATH__"] = [target.groupByValues];
    }

    return {
        frame: {
            start_row: y ?? 0,
            start_col: 0,
            paths: [key],
            column_paths: [
                ...target.splitByValues.map((v) => [v]),
                [target.columnName],
            ],
            data,
        },
        ref: y === undefined ? { x: 0 } : { y, x: 0 },
    };
}

export { PerspectiveSelectDetail } from "@perspective-dev/viewer/select-detail";
import type {
    PerspectiveHitRef,
    PerspectiveViewFrame,
} from "@perspective-dev/viewer";
